package ai.eva.android.probe;
import android.content.*;import android.app.*;import org.json.*;import java.io.*;import java.util.concurrent.*;
final class NetworkTools {
 static final ExecutorService worker=Executors.newSingleThreadExecutor();
 static JSONObject spec()throws Exception{return new JSONObject().put("name","eva_network").put("description","Local network capture and APK/PCAP analysis. status reports only Eva receiver state, not proof that the VPN engine is running. open_capture opens the phone UI; user chooses all-device or an app and grants PCAPdroid/VPN consent, never silently bypass permissions. analyze_pcap reads a workspace PCAP and returns bounded connection/DNS/TLS metadata; it does NOT decrypt TLS or expose bodies, cookies, auth headers or SSL keys. analyze_apk inventories ZIP/DEX classes and native-library names without execution; this is not Java decompilation. Capture and reverse engineering are only for the user's authorized apps and task; no purchases, sending or payment. Do not claim delivery prices were extracted when only encrypted traffic was observed.").put("inputSchema",new JSONObject().put("type","object").put("properties",new JSONObject().put("action",new JSONObject().put("type","string").put("enum",new JSONArray(new String[]{"status","open_capture","analyze_pcap","analyze_apk"}))).put("path",new JSONObject().put("type","string")).put("query",new JSONObject().put("type","string"))).put("required",new JSONArray(new String[]{"action"})).put("additionalProperties",false));}
 static JSONObject execute(Context c,JSONObject a)throws Exception{String action=a.getString("action");if(action.equals("status")){JSONObject r=new JSONObject().put("receiverActive",NetworkCaptureService.active).put("bytes",NetworkCaptureService.bytes).put("state",NetworkCaptureService.state).put("tlsDecrypted",false);File f=NetworkCaptureService.file;if(f!=null)r.put("path",WorkspaceFiles.root(c).toPath().relativize(f.toPath()).toString());return r;}if(action.equals("open_capture")){PhoneAccessibility s=PhoneAccessibility.live;if(s==null)throw new IOException("请打开 Eva 设置中的网络采集与分析");s.guard();s.startActivity(new Intent(c,NetworkCaptureActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return new JSONObject().put("opened",true).put("requiresUserConsent",true);}File f=WorkspaceFiles.resolve(c,a.getString("path"));if(action.equals("analyze_pcap"))return new JSONObject(PacketSummary.read(f).json());if(action.equals("analyze_apk"))return new JSONObject(ApkInventory.inspect(f,a.optString("query","")));throw new IOException("未知网络分析操作");}
 static boolean handle(KernelHost host,JSONObject row){if(!row.optString("method").equals("item/tool/call"))return false;JSONObject p=row.optJSONObject("params");if(p==null||!p.optString("tool").equals("eva_network"))return false;worker.execute(()->{JSONObject response=new JSONObject();try{response.put("success",true).put("contentItems",new JSONArray().put(new JSONObject().put("type","inputText").put("text",execute(host.context,p.getJSONObject("arguments")).toString())));}catch(Exception e){try{response.put("success",false).put("contentItems",new JSONArray().put(new JSONObject().put("type","inputText").put("text",String.valueOf(e.getMessage()))));}catch(Exception ignored){}}try{host.write(new JSONObject().put("id",row.get("id")).put("result",response));}catch(Exception ignored){}});return true;}
}
